def _one(conn, sql, params=None):
    return conn.execute(sa.text(sql), params or {}).scalar()


def _exec(conn, sql, params=None):
    conn.execute(sa.text(sql), params or {})


def _uuid_expr(name):
    return f"CAST(:{name} AS UUID)"


def _get_bin_id(conn, code):
    if not code:
        return None
    return _one(conn, "select id::text from storage_bins where bin_code = :code", {"code": code})


def _get_user_id(conn, employee_id):
    if not employee_id:
        return None
    return _one(conn, "select id::text from users where employee_id = :employee_id", {"employee_id": employee_id})


def _get_tool_id(conn, tool_code):
    if not tool_code:
        return None
    return _one(conn, "select id::text from tools where tool_code = :tool_code", {"tool_code": tool_code})


def _get_requisition_id(conn, requisition_number):
    if not requisition_number:
        return None
    return _one(conn, "select id::text from requisitions where requisition_number = :requisition_number", {"requisition_number": requisition_number})


def _sync_storage_bins(conn):
    for row in BASELINE["storage_bins"]:
        existing = _get_bin_id(conn, row["bin_code"])
        if existing:
            _exec(conn, """
                update storage_bins set
                    shelf_label=:shelf_label, section=:section, department_cat=:department_cat,
                    row_label=:row_label, rack_number=:rack_number, shelf_level=:shelf_level,
                    floor_area=:floor_area, description=:description, capacity=:capacity
                where bin_code=:bin_code
            """, row)
        else:
            _exec(conn, """
                insert into storage_bins (
                    id, plant_id, bin_code, shelf_label, section, department_cat, row_label,
                    rack_number, shelf_level, floor_area, description, capacity, created_at
                ) values (
                    CAST(:id AS UUID), CAST(:plant_id AS UUID), :bin_code, :shelf_label, :section,
                    :department_cat, :row_label, :rack_number, :shelf_level, :floor_area,
                    :description, :capacity, :created_at
                )
            """, row)


def _sync_users(conn):
    for row in BASELINE["users"]:
        existing = _one(conn, "select id::text from users where employee_id=:employee_id or email=:email", row)
        if existing:
            _exec(conn, """
                update users set
                    full_name=:full_name, email=:email, hashed_password=:hashed_password,
                    role=:role, department=:department, is_active=:is_active
                where id = CAST(:existing_id AS UUID)
            """, {**row, "existing_id": existing})
        else:
            _exec(conn, """
                insert into users (
                    id, plant_id, employee_id, full_name, email, hashed_password,
                    role, department, is_active, created_at
                ) values (
                    CAST(:id AS UUID), CAST(:plant_id AS UUID), :employee_id, :full_name,
                    :email, :hashed_password, :role, :department, :is_active, :created_at
                )
            """, row)


def _sync_tools(conn):
    for row in BASELINE["tools"]:
        storage_bin_id = _get_bin_id(conn, row.get("storage_bin_code"))
        params = {**row, "storage_bin_id": storage_bin_id}
        existing = _get_tool_id(conn, row["tool_code"])
        if existing:
            _exec(conn, """
                update tools set
                    plant_id=CAST(:plant_id AS UUID), name=:name, category=:category, tool_type=:tool_type,
                    department_access=:department_access, is_consumable=:is_consumable, make=:make,
                    model=:model, serial_number=:serial_number, purchase_date=:purchase_date,
                    purchase_price=:purchase_price, standard_life_months=:standard_life_months,
                    current_value=:current_value, total_quantity=:total_quantity,
                    available_quantity=:available_quantity, storage_bin_id=CAST(:storage_bin_id AS UUID),
                    requires_calibration=:requires_calibration, calibration_freq_days=:calibration_freq_days,
                    last_calibration_date=:last_calibration_date, next_calibration_due=:next_calibration_due,
                    service_partner=:service_partner, status=:status, updated_at=:updated_at
                where tool_code=:tool_code
            """, params)
        else:
            _exec(conn, """
                insert into tools (
                    id, plant_id, tool_code, name, category, tool_type, department_access, is_consumable,
                    make, model, serial_number, purchase_date, purchase_price, standard_life_months,
                    current_value, total_quantity, available_quantity, storage_bin_id, requires_calibration,
                    calibration_freq_days, last_calibration_date, next_calibration_due, service_partner,
                    status, created_at, updated_at
                ) values (
                    CAST(:id AS UUID), CAST(:plant_id AS UUID), :tool_code, :name, :category, :tool_type,
                    :department_access, :is_consumable, :make, :model, :serial_number, :purchase_date,
                    :purchase_price, :standard_life_months, :current_value, :total_quantity,
                    :available_quantity, CAST(:storage_bin_id AS UUID), :requires_calibration,
                    :calibration_freq_days, :last_calibration_date, :next_calibration_due,
                    :service_partner, :status, :created_at, :updated_at
                )
            """, params)


def _sync_requisitions(conn):
    for row in BASELINE["requisitions"]:
        params = {
            **row,
            "tool_id": _get_tool_id(conn, row["tool_code"]),
            "requested_by": _get_user_id(conn, row["requested_by_employee_id"]),
            "approved_by": _get_user_id(conn, row.get("approved_by_employee_id")),
        }
        existing = _get_requisition_id(conn, row["requisition_number"])
        if existing:
            _exec(conn, """
                update requisitions set
                    plant_id=CAST(:plant_id AS UUID), tool_id=CAST(:tool_id AS UUID),
                    requested_by=CAST(:requested_by AS UUID), requester_dept=:requester_dept,
                    quantity_requested=:quantity_requested, purpose_of_job=:purpose_of_job,
                    from_date=:from_date, to_date=:to_date, status=:status,
                    approved_by=CAST(:approved_by AS UUID), approved_at=:approved_at,
                    rejection_reason=:rejection_reason, updated_at=:updated_at
                where requisition_number=:requisition_number
            """, params)
        else:
            _exec(conn, """
                insert into requisitions (
                    id, plant_id, requisition_number, tool_id, requested_by, requester_dept,
                    quantity_requested, purpose_of_job, from_date, to_date, status, approved_by,
                    approved_at, rejection_reason, created_at, updated_at
                ) values (
                    CAST(:id AS UUID), CAST(:plant_id AS UUID), :requisition_number,
                    CAST(:tool_id AS UUID), CAST(:requested_by AS UUID), :requester_dept,
                    :quantity_requested, :purpose_of_job, :from_date, :to_date, :status,
                    CAST(:approved_by AS UUID), :approved_at, :rejection_reason, :created_at, :updated_at
                )
            """, params)


def _sync_issuance_logs(conn):
    for row in BASELINE["issuance_logs"]:
        requisition_id = _get_requisition_id(conn, row["requisition_number"])
        params = {
            **row,
            "requisition_id": requisition_id,
            "tool_id": _get_tool_id(conn, row["tool_code"]),
            "issued_to": _get_user_id(conn, row["issued_to_employee_id"]),
            "issued_by": _get_user_id(conn, row["issued_by_employee_id"]),
        }
        existing = _one(conn, "select id::text from issuance_logs where requisition_id=CAST(:requisition_id AS UUID)", params)
        if existing:
            _exec(conn, """
                update issuance_logs set
                    plant_id=CAST(:plant_id AS UUID), tool_id=CAST(:tool_id AS UUID),
                    issued_to=CAST(:issued_to AS UUID), issued_by=CAST(:issued_by AS UUID),
                    quantity_issued=:quantity_issued, issued_at=:issued_at,
                    expected_return_date=:expected_return_date, actual_return_date=:actual_return_date,
                    return_condition=:return_condition, quantity_returned=:quantity_returned,
                    quantity_consumed=:quantity_consumed, damage_type=:damage_type,
                    penalty_amount=:penalty_amount, depreciated_value_at_issue=:depreciated_value_at_issue,
                    market_rate_at_damage=:market_rate_at_damage, notes=:notes, updated_at=:updated_at
                where id=CAST(:existing_id AS UUID)
            """, {**params, "existing_id": existing})
        else:
            _exec(conn, """
                insert into issuance_logs (
                    id, plant_id, requisition_id, tool_id, issued_to, issued_by, quantity_issued,
                    issued_at, expected_return_date, actual_return_date, return_condition,
                    quantity_returned, quantity_consumed, damage_type, penalty_amount,
                    depreciated_value_at_issue, market_rate_at_damage, notes, created_at, updated_at
                ) values (
                    CAST(:id AS UUID), CAST(:plant_id AS UUID), CAST(:requisition_id AS UUID),
                    CAST(:tool_id AS UUID), CAST(:issued_to AS UUID), CAST(:issued_by AS UUID),
                    :quantity_issued, :issued_at, :expected_return_date, :actual_return_date,
                    :return_condition, :quantity_returned, :quantity_consumed, :damage_type,
                    :penalty_amount, :depreciated_value_at_issue, :market_rate_at_damage,
                    :notes, :created_at, :updated_at
                )
            """, params)


def _sync_notifications(conn):
    for row in BASELINE["notifications"]:
        params = {**row, "user_id": _get_user_id(conn, row["user_employee_id"])}
        existing = _one(conn, "select id::text from notifications where id=CAST(:id AS UUID)", params)
        if existing:
            _exec(conn, """
                update notifications set
                    plant_id=CAST(:plant_id AS UUID), user_id=CAST(:user_id AS UUID),
                    message=:message, is_read=:is_read, created_at=:created_at
                where id=CAST(:id AS UUID)
            """, params)
        else:
            _exec(conn, """
                insert into notifications (id, plant_id, user_id, message, is_read, created_at)
                values (CAST(:id AS UUID), CAST(:plant_id AS UUID), CAST(:user_id AS UUID), :message, :is_read, :created_at)
            """, params)


def upgrade() -> None:
    conn = op.get_bind()
    _sync_storage_bins(conn)
    _sync_users(conn)
    _sync_tools(conn)
    _sync_requisitions(conn)
    _sync_issuance_logs(conn)
    _sync_notifications(conn)


